SELECT 
FROM daily_bar
WHERE instrument_id = #{instrumentId}
  AND trade_date BETWEEN #{from} AND #{to}
ORDER BY trade_date

SELECT 
FROM (
    SELECT 
    FROM daily_bar
    WHERE instrument_id = #{instrumentId}
    ORDER BY trade_date DESC
    LIMIT #{limit}
)
ORDER BY trade_date

SELECT trade_date, close
FROM daily_bar
WHERE instrument_id = #{instrumentId}
  AND trade_date BETWEEN #{from} AND #{to}
ORDER BY trade_date
